INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (1, 125801, 1, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 24001, 321, 40011, 2, 1, 0, "リリ");
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (1, 126001, 1, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 24001, 322, 40011, 2, 2, 0, "クリア");
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (1, 126101, 1, "んーと。\nこれ、あげる。\nはい", 24001, 323, 40011, 2, 3, 0, "プレシア");
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (2, 125801, 1, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 24001, 324, 40011, 2, 4, 0, "リリ");
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (2, 126001, 1, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 24001, 325, 40011, 2, 5, 0, "クリア");
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (2, 126101, 1, "お兄。\nきてくれて、うれしい", 24001, 326, 40011, 2, 6, 0, "プレシア");
